+import type { SessionEvent } from '../types.ts';
+
+// Shortcuts that make work look done. The scan reads only what the run changed: the snapshot patch when there are
+// snapshots, otherwise the edit and write calls. It flags; it never refuses.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; detail?: string };
+
+const TEST_FILE = /(\.test\.|\.spec\.|_test\.|(^|\/)test_[^/]*$|(^|\/)tests?\/|__tests__)/;
+const CODE_FILE = /\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs|java|kt|rb|php|cs|swift|c|cc|cpp|h|hpp)$/;
+const ASSERTION = /\bexpect\(|\bassert\b|\bassert[A-Z]\w*\(/;
+const SKIP = /\b(test|it|describe)\.skip\(|\bx(it|describe|test)\(|\bt\.Skip(f|Now)?\(|@pytest\.mark\.skip|#\[ignore\]/;
+const SUPPRESSION = /@ts-(ignore|expect-error|nocheck)\b|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint\b/;
+const SWALLOWED = /catch\s*(\([^)]*\))?\s*\{\s*\}|^\s*except\b[^:]*:\s*pass\s*$/;
+const TYPE_ESCAPE = /\bas any\b|:\s*any\b|<any>/;
+const STUB = /not implemented|NotImplementedError|\bunimplemented!\(|\btodo!\(/i;
+
+// Per-line rules, in the order a line is matched: the first one that fits names it.
+const LINE_RULES: { rule: string; test: RegExp; testOnly?: boolean }[] = [
+  { rule: 'test-skipped', test: SKIP, testOnly: true },
+  { rule: 'suppression', test: SUPPRESSION },
+  { rule: 'swallowed-error', test: SWALLOWED },
+  { rule: 'type-escape', test: TYPE_ESCAPE },
+  { rule: 'stub', test: STUB },
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    const isTest = TEST_FILE.test(c.path);
+    if (c.deleted) {
+      if (isTest) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (!CODE_FILE.test(c.path)) continue;
+    if (isTest) {
+      const count = (xs: string[]) => xs.filter((l) => ASSERTION.test(l)).length;
+      if (count(c.added) < count(c.removed)) out.push({ rule: 'test-weakened', path: c.path });
+    }
+    for (const line of c.added) {
+      const hit = LINE_RULES.find((r) => (isTest || !r.testOnly) && r.test.test(line));
+      if (hit) out.push({ rule: hit.rule, path: c.path, detail: line.trim().slice(0, 120) });
+    }
+  }
+  return out;
+}
+
+export const flagText = (f: Finding) => `${f.rule} ${f.path}${f.detail ? `: ${f.detail}` : ''}`;
+
+// A git patch made with -U0, as `git diff-tree -p -U0` writes it. Only the hunk lines count.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/(.*) b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[2]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+      continue;
+    }
+    if (!cur) continue;
+    if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk) {
+      if (line.startsWith('deleted file mode')) cur.deleted = true;
+    } else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots, the changes are the edit and write calls that completed.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const status = new Map<string, string>();
+  for (const e of events) if (e.kind === 'tool_result') status.set(e.callId, e.status);
+  const out: FileChange[] = [];
+  for (const e of events) {
+    if (e.kind !== 'tool_intent' || status.get(e.callId) !== 'completed') continue;
+    const path = String(e.input.path ?? '');
+    if (e.tool === 'write') {
+      out.push({ path, added: String(e.input.content ?? '').split('\n'), removed: [], deleted: false });
+    } else if (e.tool === 'edit') {
+      const change: FileChange = { path, added: [], removed: [], deleted: false };
+      for (const ed of (Array.isArray(e.input.edits) ? e.input.edits : []) as { old_text?: unknown; new_text?: unknown }[]) {
+        change.removed.push(...String(ed.old_text ?? '').split('\n'));
+        change.added.push(...String(ed.new_text ?? '').split('\n'));
+      }
+      out.push(change);
+    }
+  }
+  return out;
+}
