+// Shortcuts that make work look done. Scanned on the run's own changes at a done claim; findings are flags, not refusals.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type Finding = { rule: SlopRule; path: string; line?: string };
+
+const TEST_FILE = /(^|\/)(tests?|__tests__)\/|\.(test|spec)\.[cm]?[jt]sx?$|_test\.(go|py)$|(^|\/)test_[^/]*\.py$/;
+const CODE_FILE = /\.([cm]?[jt]sx?|py|go|rs|java|kt|rb|cs|cpp|cc|c|h|hpp|swift|php)$/;
+const ASSERT = /\bassert|\bexpect\(|\.should\b|\bt\.(Error|Errorf|Fatal|Fatalf)\(|assert_eq!|assert!/;
+const SKIP = /\b(test|it|describe|suite)\.skip\(|\bx(it|describe|test)\(|\bt\.Skip(Now)?\(|@pytest\.mark\.skip|@unittest\.skip|#\[ignore\]/;
+const SUPPRESS = /@ts-(ignore|nocheck|expect-error)|eslint-disable|#\s*type:\s*ignore|#\s*noqa|#\s*pylint:\s*disable|\/\/\s*nolint|#\[allow\(/;
+const SWALLOW = /catch\s*(\([^)]*\))?\s*\{\s*\}|^\s*except\b.*:\s*pass\s*$/;
+const TYPE_ESCAPE = /\bas any\b|:\s*any\b/;
+const STUB = /not implemented|NotImplementedError|\btodo!\(|\bunimplemented!\(/i;
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    if (TEST_FILE.test(c.path)) {
+      if (c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+      else if (c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length) out.push({ rule: 'test-weakened', path: c.path });
+    }
+    if (c.deleted || !CODE_FILE.test(c.path)) continue;
+    for (const line of c.added) {
+      if (TEST_FILE.test(c.path) && SKIP.test(line)) out.push({ rule: 'test-skipped', path: c.path, line: line.trim() });
+      if (SUPPRESS.test(line)) out.push({ rule: 'suppression', path: c.path, line: line.trim() });
+      if (SWALLOW.test(line)) out.push({ rule: 'swallowed-error', path: c.path, line: line.trim() });
+      if (TYPE_ESCAPE.test(line)) out.push({ rule: 'type-escape', path: c.path, line: line.trim() });
+      if (STUB.test(line)) out.push({ rule: 'stub', path: c.path, line: line.trim() });
+    }
+  }
+  return out;
+}
+
+export const slopLabel = (f: Finding) => (f.line ? `${f.rule} ${f.path}: ${f.line}` : `${f.rule} ${f.path}`);
+
+// Parses a `git diff -U0` patch. Hunk lines start with +/- only after the first @@ of a file, so +++/--- headers are skipped.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+  }
+  return out;
+}
