--- a/test/pricing-rules.test.ts	1970-01-01 07:00:00
+++ b/test/pricing-rules.test.ts	2026-10-27 23:31:29
@@ -0,0 +1,32 @@
+import { expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// A mug is 450 cents.
+test('bulk tiers start at exactly 10 and 50 units', () => {
+  // 10 mugs = 4500; 5% off = 225 -> 4275
+  expect(totals(cart('US', [['MUG', 10]])).subtotal).toBe(4275);
+  // 50 mugs = 22500; 10% off = 2250 -> 20250
+  expect(totals(cart('US', [['MUG', 50]])).subtotal).toBe(20250);
+  // 9 mugs = 4050; no discount
+  expect(totals(cart('US', [['MUG', 9]])).subtotal).toBe(4050);
+});
+
+test('UK free shipping starts at 4000', () => {
+  // 2 bags = 4400 >= 4000 ships free
+  expect(totals(cart('UK', [['BAG', 2]])).shipping).toBe(0);
+});
+
+test('shipping threshold uses the discounted subtotal', () => {
+  // 3 bags = 6600 in US; SAVE10 takes 660 -> 5940 >= 5000 -> free shipping
+  const t = totals(cart('US', [['BAG', 3]], 'SAVE10'));
+  expect(t.coupon).toBe(660);
+  expect(t.shipping).toBe(0);
+});
+
+test('lines of the same SKU are merged before bulk pricing', () => {
+  // 6 + 4 mugs = 10 units -> 4275
+  const t = totals(cart('US', [['MUG', 6], ['MUG', 4]]));
+  expect(t.subtotal).toBe(4275);
+  expect(t.lines.length).toBe(1);
+});

