+  if (!new RegExp(`^(?:${part.source}\\s*)+$`).test(trimmed)) {
+    throw new Error(`invalid duration: "${text}"`);
+  }
+  let total = 0;
+  for (const match of trimmed.matchAll(new RegExp(part.source, 'g'))) {
+    total += Number(match[1]) * UNIT_MS[match[2]];
+  }
+  return Math.round(total);
